{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "A payment plan can be created with `create_payment_plan` if the current balance is at least 100 USD and the account has no `broken_plan` within the last 6 months.",
      "requirement": "The account's current balance must be at least 100 USD (exception: no minimum balance requirement if the account is commercial, but this is a residential account)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "The plan must have between 3 and 6 monthly installments, as chosen by the customer.",
      "requirement": "The number of installments must be between 3 and 6 months (inclusive)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "The installment amount equals balance / months, rounded to the cent.",
      "requirement": "The installment amount must equal the balance divided by the number of months, rounded to the nearest cent."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "Before `create_payment_plan`, present the details and get explicit confirmation (\"yes\"/\"да\") from the customer. If the customer changes the details, use the latest details the customer confirmed.",
      "requirement": "Explicit confirmation from the customer must be obtained before creating the payment plan, using the exact details they confirmed."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q12",
      "policy_quote": "You help residential customers with billing: balances, late fee waivers, payment plans and refunds of overpayments. You cannot change tariffs, meter readings or service addresses.",
      "requirement": "The action must only address billing-related issues (balances, late fees, payment plans, or refunds) and must not involve tariffs, meter readings, or service addresses."
    }
  ]
}
